// AI: below section was generated by an AI
import { rpc as request } from './request.js';
import { renderFirmware, shareCurrentFirmware } from './updates.js';
import { deviceOverview } from './devices.js';
import { uploadFirmware } from './upload.js';
const $ = id => document.getElementById(id);
let address = location.protocol === 'file:' ? '' : location.origin;
let currentStatus, busy = false, connected = false;
$('address').value = address;
const message = text => { $('message').textContent = text; };
const rpc = command => request(address, command);

// Queue tab operations so uploads and status polling do not compete for bounded device resources.
async function action(operation) {
	if (busy) return;
	busy = true;
	try { await operation(); } catch (error) { message(error.message); }
	finally { busy = false; }
}
async function refresh() {
	const status = await rpc({op: 'status'}); currentStatus = status;
	$('role').textContent = status.controlEnabled === false ? 'Observer · discovery and firmware updates active' : !status.settled ? 'Electing a master…' : status.master ? 'Connected to the master' : 'Connected to a follower';
	$('leader').textContent = 'Master: ' + status.masterId + ' · ' + status.masterIp;
	const overview = deviceOverview(status);
	for (const id of ['connection', 'deviceOverview', 'targetControls']) $(id).hidden = !overview.visible;

	const previous = $('target').value;
	$('target').replaceChildren(new Option(overview.visible ? 'All devices' : 'This device', overview.visible ? 'all' : status.localId));
	$('devices').replaceChildren();
	for (const device of overview.visible ? overview.physicalDevices : []) {
		$('target').append(new Option((device.name || device.id) + (device.id === status.localId ? ' (this device)' : ''), device.id));
		const row = document.createElement('tr');
		for (const text of [device.name || device.id, device.ip, device.version, device.sync ? 'On' : 'Off', device.result || '—']) {
			const cell = document.createElement('td'); cell.textContent = text; row.append(cell);
		}
		$('devices').append(row);
	}
	if ([...$('target').options].some(option => option.value === previous)) $('target').value = previous;
	for (const id of ['applyLighting', 'applySettings']) $(id).disabled = !status.master || !status.settled;
	renderFirmware(status, $);
	return status;
}
// A device-hosted page connects automatically. Standalone pages need only the device address.
async function connect() {
	const url = new URL($('address').value);
	if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.pathname !== '/' || url.search || url.hash) throw new Error('Enter only the device origin, for example http://192.168.1.50');
	address = url.origin;
	await refresh();
	const effects = await rpc({op: 'effects'});
	$('effect').replaceChildren(...effects.effects.map((name, id) => new Option(name, String(id))));
	connected = true;
	message('Connected. No dashboard login is required.');
}
$('connect').onclick = () => action(connect);
$('refresh').onclick = () => action(refresh);
$('applyLighting').onclick = () => action(async () => {
	const color = $('color').value.match(/[0-9a-f]{2}/gi).map(part => parseInt(part, 16));
	const result = await rpc({op: 'lighting', target: $('target').value, body: {
		on: $('power').checked, bri: Number($('brightness').value),
		seg: [{id: 0, col: [color], fx: Number($('effect').value), sx: Number($('speed').value), ix: Number($('intensity').value)}]
	}});
	message(deviceOverview(currentStatus).visible ? 'Applied locally or queued for ' + result.accepted + ' device(s). Check acknowledgements in the device table.' : 'Lighting applied.');
});
$('applySettings').onclick = () => action(async () => {
	const body = {sync: $('sync').checked, bootOn: $('bootOn').checked, bootBrightness: Number($('bootBrightness').value), transitionMs: Number($('transition').value)};
	if ($('name').value) body.name = $('name').value;
	await rpc({op: 'settings', target: $('target').value, body}); message(deviceOverview(currentStatus).visible ? 'Settings applied locally or queued. Check device acknowledgements.' : 'Settings saved.');
});
$('upload').onclick = () => action(async () => {
	await uploadFirmware(rpc, $('firmware').files[0], (received, total) => {
		$('progress').hidden = false;
		$('progress').value = Math.round(100 * received / total);
		$('firmwareStatus').textContent = 'Uploading firmware: ' + received + '/' + total + ' bytes';
	});
	await refresh(); message('Firmware staged and SHA-256 verified. Ready to distribute.');
});
$('shareCurrent').onclick = () => action(async () => {
	const target = $('firmwareTarget').value;
	message('Preparing this device’s running firmware. Progress is shown below.');
	const result = await shareCurrentFirmware(rpc, refresh, target);
	await refresh(); message('Update queued for ' + result.queued + ' follower(s). Watch each device’s transfer and reboot status below.');
});
$('rollout').onclick = () => action(async () => {
	const result = await rpc({op: 'rollout', target: $('firmwareTarget').value});
	await refresh(); message('Update queued for ' + result.queued + ' follower(s); ' + (result.skipped || 0) + ' already have this build. Watch progress below.');
});
$('installLocal').onclick = () => action(async () => { if (!confirm('Install the staged firmware on this master? Update and verify followers first.')) return; await rpc({op: 'installLocal'}); message('Master update started. It will reboot after verification.'); });
$('saveWifi').onclick = () => action(async () => {
	await rpc({op: 'wifi', confirm: true, body: {ssid: $('ssid').value, password: $('wifiPassword').value}});
	$('wifiPassword').value = ''; message('Wi-Fi saved on this device. Reboot to connect.');
});
$('reboot').onclick = () => action(async () => { await rpc({op: 'reboot'}); message('Device reboot requested. Reconnect after startup.'); });
if (address) action(connect);
else { $('connection').hidden = false; message('Enter the device address to connect.'); }
setInterval(() => { if (!busy && address) action(connected ? refresh : connect); }, 1000);
// AI: end
